// UNVERIFIED: best-guess extraction pending a real Sendchamp/WABA payload.
// Meta Cloud API interactive-reply webhooks typically nest the button tap
// under entry[].changes[].value.messages[].interactive.button_reply, with
// the sender's number at messages[].from and (for replies) the original
// outbound message id echoed back at messages[].context.id. Sendchamp may
// pass this through directly or reshape it — adjust the paths below once
// a real payload is captured.
const body = $json.body ?? $json;

const waMessage =
  body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0] // Meta Cloud API shape, if passed through as-is
  ?? body?.data?.message // plausible Sendchamp-flattened shape
  ?? body;

const fromPhoneRaw = waMessage?.from ?? body?.phone_number ?? body?.sender ?? null;
// Normalize to the +234E.164 format stored in members.phone_number.
const fromPhone = fromPhoneRaw
  ? (fromPhoneRaw.startsWith('+') ? fromPhoneRaw : `+${fromPhoneRaw.replace(/^0/, '234')}`)
  : null;

const buttonReply = waMessage?.interactive?.button_reply ?? waMessage?.button ?? null;
const buttonId = buttonReply?.id ?? buttonReply?.payload ?? null;
const buttonText = buttonReply?.title ?? buttonReply?.text ?? null;
const contextMessageId = waMessage?.context?.id ?? body?.context_id ?? null;

return [{
  json: {
    from_phone: fromPhone,
    context_message_id: contextMessageId,
    button_id: buttonId,
    button_text: buttonText,
    raw_payload: JSON.stringify(body),
  },
}];

const match = $('Find Matching Message Log Row').first()?.json;
const reply = $('Parse Interactive Reply').first().json;

if (!match || !match.message_log_id) {
  return [{
    json: { matched: false, reason: 'No matching outbound WhatsApp message found for this reply', ...reply },
  }];
}

const id = (reply.button_id || '').toLowerCase();
let interpreted_reply = 'unrecognized';
if (id.includes('rsvp_yes') || id.includes('accept')) interpreted_reply = 'rsvp_yes';
else if (id.includes('rsvp_no') || id.includes('decline')) interpreted_reply = 'rsvp_no';
else if (id.includes('payment') || id.includes('paid')) interpreted_reply = 'payment_confirmed';

return [{
  json: {
    matched: true,
    message_log_id: match.message_log_id,
    broadcast_id: match.broadcast_id,
    member_id: match.member_id,
    interpreted_reply,
    reply_payload: reply.button_text || reply.button_id || reply.raw_payload,
  },
}];
